// from src/locales/ja/blog.ts. Body + FAQs for article 'base64-to-image-guide' (ja).
// This file is the single source for this article's ja body text.
import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>メールやチャットメッセージ、APIの応答に、長いテキストの壁が届き、その中に画像が隠れていることがあります。そのテキストはBase64文字列で、画像はデコードされるのを待っています。</p>\n<p>デコードは、その文字列を元の画像ファイルに戻します。エンコードの逆で、同じく劣化がありません。出てくるバイトは、入ったバイトとまったく同じです。</p>\n<p>この記事では、CompressMyPicのBase64画像デコーダーの仕組み、受け付けるもの、表示する内容、あらゆるBase64文字列から使える画像ファイルを得る方法を解説します。</p>\n<h2 id=\"what-is-base64-to-image\">Base64画像デコーダーとは？</h2>\n<p>Base64画像デコーダーは、テキスト文字列を受け取り、表示・ダウンロード・利用できる画像ファイルに戻すツールです。エンコードの処理を正確に逆転させます。</p>\n<p>文字列をツールに貼り付けると、デコードされた画像がサイズとファイル容量付きのプレビューで表示されます。次に、元の形式かPNG、JPG、WebPに変換してダウンロードします。</p>\n<p>ツールは、data:imageの接頭辞がある文字列も、ない文字列も受け付けます。URLセーフ版や、メールや文書からのコピーでよくある意図しない改行が入った文字列にも対応します。</p>\n<p>すべてブラウザ内でローカルに動作します。文字列はデバイス上でデコードされ、テキストも画像もサーバーにアップロードされません。</p>\n<h2 id=\"how-decoding-works\">Base64デコードの仕組み</h2>\n<p>デコードは、文字列を4文字ずつ読みます。4文字の各グループは24ビットのデータを運び、デコーダーがそれを元のファイルの3バイトに戻します。</p>\n<p>文字列の末尾の等号は埋め草で、最後のグループが何バイト持つかをデコーダーに伝えます。等号1つは2バイト、2つは1バイトです。</p>\n<p>この処理は正確です。正しくエンコードされた文字列は、品質も、アニメーションも、透明度も失うことなく、エンコードされたファイルとバイト単位で同じファイルにデコードされます。</p>\n<p>文字列が損傷している場合、デコーダーは壊れた画像を作るのではなく、明確なエラーで失敗します。この速やかな失敗は大切です。黙って壊れた画像は、正直なエラーより悪いからです。</p>\n<h2 id=\"with-and-without-prefix\">data:imageの接頭辞がある場合とない場合</h2>\n<p>Base64画像の文字列には2つの形があります。完全なData URLはdata:image/png;base64で始まり、その後に文字列が続きます。生の文字列は、エンコードされた文字だけです。</p>\n<p>デコーダーは両方を受け付けます。Webページからの完全なData URLを貼り付けても、JSONデータからの生の文字列を貼り付けても、ツールはどちらの形かを見分けます。</p>\n<p>これは大切なことです。2つの形は違う場所に現れます。WebコードはData URLを使い、APIやデータベースはたいてい、メディアタイプを別のフィールドに置いた生の文字列を保存します。</p>\n<p>文字列を貼り付けるときは、data:で始まるか確認しましょう。始まる場合はメディアタイプがすでに宣言されています。始まらない場合は、デコーダーが画像ヘッダーを読んで形式を自分で特定します。</p>\n<h2 id=\"url-safe-and-line-breaks\">URLセーフ版と改行</h2>\n<p>標準のBase64はプラスとスラッシュを使いますが、これらはURLの中で特別な意味を持ちます。URLセーフ版は、それらをダッシュとアンダースコアに置き換え、文字列をWebアドレスの中で安全に移動できるようにします。</p>\n<p>デコーダーは両方の文字セットを理解します。URLパラメーターからコピーした文字列も、JSONファイルからコピーした文字列も、手動での変換なしで同じようにデコードされます。</p>\n<p>改行もよくある事故です。メールクライアントや文書は長い文字列を複数行に折り返し、エンコードの一部ではない改行を挿入します。</p>\n<p>デコーダーはそうした改行を許容して無視します。余分なスペースも許容するため、折り返されたり、引用符で囲まれたり、周囲に空白を伴って貼り付けられたりした文字列も、正しくデコードされます。</p>\n<h2 id=\"auto-decode-on-paste\">貼り付けると自動デコード</h2>\n<p>デコードするためにボタンをクリックする必要はありません。Base64文字列をツールに貼り付けると、自動的にデコードが始まり、数秒でプレビューが表示されます。</p>\n<p>自動デコードは、多くの文字列を処理するときに役立つ小さな便利さです。貼り付けて、プレビューを確認し、ダウンロードして、次の文字列を貼り付ける。1枚ごとに余分なクリックは不要です。</p>\n<p>非常に長い文字列の場合、デコードに1〜2秒かかることがあります。数MBの文字列は大量のテキストを運ぶため、ブラウザはそれをバイナリデータに戻すのに少し時間を必要とします。</p>\n<p>ツールはブラウザが許す限り速くデコードし、サーバーへの往復で遅くなることはありません。大きな文字列も、自分のデバイスの速度でデコードされます。</p>\n<h2 id=\"checkerboard-preview\">チェック柄のプレビュー</h2>\n<p>デコードされた画像はチェック柄の背景の上に表示されます。グレーと白のマスが、画像が透けて見える場所を示す、透明度を表す標準的な方法です。</p>\n<p>チェック柄は、アイコンやロゴに特に役立ちます。透明な背景を持つPNGは、白いページの上では白い背景のPNGと同じに見えますが、チェック柄なら違いがすぐに分かります。</p>\n<p>本来ベタ塗りのはずの画像の真ん中からチェック柄が見える場合、その画像には本当にそこに透明度があります。ファイルについての情報であって、デコーダーの欠陥ではありません。</p>\n<p>プレビューを使って、ダウンロード形式を決めましょう。保持すべき透明度がある画像は、JPGではなくPNGか元の形式でダウンロードします。</p>\n<h2 id=\"metrics-shown\">表示される数値：サイズ・形式・容量</h2>\n<p>プレビューの横に、ツールはデコードされた画像のピクセル単位のサイズ、検出された形式、KBまたはMB単位のバイナリファイルサイズを表示します。</p>\n<p>バイナリサイズは、貼り付けたBase64テキストより常に約4分の1小さいです。これは33%のエンコードの増加が逆に働いているためで、差は予想どおりです。</p>\n<p>サイズは、その画像が目的に使えるかどうかを教えてくれます。文字列からデコードされた64×64のアイコンはファビコンであってヒーロー画像ではなく、ダウンロード形式を変えてもそれは変わりません。</p>\n<p>形式も確認しましょう。PNGだと主張する文字列がJPEGとしてデコードされる場合、元について何かを示しており、ダウンロードの選択肢はファイルの実際の姿に合わせて調整されます。</p>\n<h2 id=\"download-formats\">ダウンロード形式：元の形式・PNG・JPG・WebP</h2>\n<p>文字列がデコードされたら、ダウンロード形式を選びます。「元の形式」は、エンコードされたときとまったく同じファイルをバイト単位で保ちます。分からないときは最も安全な選択です。</p>\n<p>PNGは、透明度やシャープな縁のある画像に適しています。ピクセルを正確に保ち、アルファチャンネルも維持するため、ロゴやアイコンが往復を無事に乗り越えます。</p>\n<p>JPGは、小さくしたい写真に適しています。画像を圧縮して透明度を落とすため、画像が完全に不透明な場合にだけ使いましょう。</p>\n<p>WebPは、現代的な中間点です。ほとんどの画像でPNGより小さく、透明度にも対応しています。送信先が最近のWebサイトなら良い標準です。すべてのダウンロードは、対応する拡張子付きでdecoded_imageという名前になります。ダウンロードフォルダで簡単に見つけられます。</p>\n<h2 id=\"transparency-and-jpg\">透明度とJPGの落とし穴</h2>\n<p>透明度は、デコードするときに最も失いやすいものです。透明な背景を持つPNGをJPGとしてダウンロードすると、透明な部分がたいてい白や黒で塗りつぶされます。</p>\n<p>その塗りつぶしは永久です。JPGとして保存されれば、透明度の情報は失われ、PNGに変換し直しても戻りません。</p>\n<p>JPGを選ぶ前に、必ずチェック柄のプレビューを確認しましょう。画像のどこかにチェック柄が見える場合、その画像には透明度があり、JPGは間違った形式です。</p>\n<p>迷ったら、「元の形式」でダウンロードしましょう。エンコードされたときとまったく同じファイルが保たれ、きちんと確認してから変換できます。</p>\n<h2 id=\"animated-gif-and-svg\">アニメーションGIFとベクターSVG</h2>\n<p>アニメーションGIFは、「元の形式」でダウンロードすれば、デコードしてもそのまま残ります。フレームも、タイミングも、ループ設定も、すべてバイナリデータの一部で、デコードが正確に復元します。</p>\n<p>アニメーションGIFをPNGやJPGに変換すると、アニメーションは壊れます。これらの形式は1枚の静止画しか持たないためです。ツールは、変換結果のプレビューで最初のフレームだけを表示して知らせます。</p>\n<p>SVGファイルはベクターで、エンコードされたときと同じSVGコードにデコードされます。「元の形式」でダウンロードすれば、有効なSVGファイルになり、拡大してもシャープさが落ちません。</p>\n<p>デコードしたSVGをラスターPNGに変換することもできます。送信先が拡大可能なベクターではなく固定サイズの画像を必要とする場合に役立ち、ツールはSVGを固有サイズでくっきりと描画します。</p>\n<h2 id=\"error-handling\">壊れた文字列の扱い</h2>\n<p>破損したBase64文字列や、画像ではないBase64文字列は、明確なエラーメッセージとともに失敗します。ツールは推測せず、部分的または壊れた画像ファイルを作りません。</p>\n<p>よくある原因は、コピー時に切り捨てられた文字列、チャットアプリや文書編集ソフトで変更された文字、そもそも画像ではなかった文字列です。</p>\n<p>エラーが表示されたら、まず文字列を確認しましょう。可能なら元の文字列と長さを比べ、切り捨てが起きやすい先頭や末尾で文字が欠けていないか探します。</p>\n<p>文字列がAPIの応答から来た場合は、応答自体が途中で切れていないか確認します。途中で切れたJSONデータは途中で切れた文字列を生み、デコーダーが欠けた末尾を修復することはできません。</p>\n<h2 id=\"svg-without-base64-marker\">base64マーカーのないSVG</h2>\n<p>一部のSVG Data URLは、まったくBase64ではありません。SVGコードをURLエンコードされたテキストとして直接運び、data:image/svg+xmlのように見えて、セミコロンとbase64のマーカーがありません。</p>\n<p>そうした文字列をデコーダーに貼り付けると、エンコードエラーになります。ツールはBase64文字を期待しているのに、山かっこや引用符が見つかるからです。</p>\n<p>対処法は、その形を見分けることです。文字列の中にsvgやpathのような読み取れるSVGタグが含まれていれば、それはプレーンなSVG Data URLであってBase64ではなく、デコードは不要です。</p>\n<p>代わりに、そのテキストを直接.svgファイルとして保存しましょう。テキストエディタを開き、デコードされたSVGコードを貼り付けて、svg拡張子で保存すれば有効なベクターファイルになります。</p>\n<h2 id=\"privacy-local-processing\">プライバシー：デコードはブラウザ内で行われる</h2>\n<p>Base64文字列は、機密性の高い内容を運ぶことがよくあります。内部のAPI応答、プライベートなアイコン、QRトークン、機密の図などです。そうした文字列をアップロードするオンラインツールに貼り付けるのはリスクです。</p>\n<p>このデコーダーはローカルで動作します。文字列はブラウザに貼り付けられ、デバイス上でデコードされ、結果の画像が自分のパソコンから外に出ることはありません。</p>\n<p>ページを一度読み込めば、オフラインでも使えます。飛行機の中や安全なオフィス、接続のない場所でも文字列をデコードできます。</p>\n<p>内部データを扱うチームにとって、ローカルでのデコードこそツールが安全に使える理由です。文字列も画像も、自分のパソコン以外にはどこにもコピーが存在しません。</p>\n<h2 id=\"decoding-from-documents-and-qr\">文書の中に見つけた画像のデコード</h2>\n<p>Base64文字列は、予想外の場所に隠れています。Word文書やPDF、デザインファイルは、埋め込まれた画像をXMLやJSON構造の中にBase64として保存することがあり、コピーした断片を直接デコードできます。</p>\n<p>そうした断片を見つけたら、文字列を全長まできちんとコピーしましょう。文書形式は長い文字列を複数行に分割することが多いため、テキストが折り返されたときに文字が失われていないか確認します。</p>\n<p>QRコードは別のケースです。QRコードはData URLとして小さな画像を含むことができますが、ほとんどのQRコードはリンクを持っています。コードがdata:imageで始まるテキストにデコードされる場合は、そのテキストをデコーダーに貼り付けます。</p>\n<p>チャットアプリもよくある入手元です。一部のチャットシステムは、メッセージデータの中に画像をBase64として送信し、コピーしたデータをデコードすれば元の写真を取り戻せます。</p>\n<p>どの場合も、同じ確認が当てはまります。文字列が完全か確認し、末尾での切り捨てに注意し、まず「元の形式」でダウンロードしましょう。元の形式こそ真実で、変換はそれを見てからで十分です。</p>\n<p>信頼できない文書からの文字列には注意しましょう。デコード自体は安全ですが、周囲の文書がフィッシングの試みの可能性もあるため、画像の内容も予期せぬ添付ファイルと同じ疑いを持って扱ってください。</p>\n<h2 id=\"how-to-use-the-tool\">Base64画像デコーダーの使い方</h2>\n<p><a href=\"/ja/base64-gazo-henkan/\">Base64画像デコーダー</a>を開き、文字列を入力欄に貼り付けます。デコードは自動的に始まり、サイズとファイル容量付きのプレビューが表示されます。</p>\n<p>チェック柄のプレビューで透明度を確認し、ダウンロード形式を選びます。ファイルを正確に保つ「元の形式」か、変換するPNG、JPG、WebPです。ファイルは、対応する拡張子付きでdecoded_imageとしてダウンロードされます。</p>\n<p>文字列が失敗したら、エラーメッセージを読んで、切り捨てや接頭辞の欠落がないか確認します。ほとんどの失敗は、損傷した文字列であってツールの問題ではありません。</p>\n<p>手順版は<a href=\"/ja/blog/base64-gazo-henkan-houhou/\">Base64を画像に変換する方法</a>、性能比較は<a href=\"/ja/blog/base64-gazo-fairu-hikaku/\">Base64と画像ファイル：性能と使いどころ</a>をご覧ください。最初に文字列を作るには、<a href=\"/ja/gazo-base64-henkan/\">画像Base64エンコーダー</a>を使います。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"埋め草が欠けたBase64文字列もデコーダーは扱えますか？","answer":"どれだけ欠けているかによります。末尾の等号だけが欠けた文字列は、長さから埋め草を推測できるため、デコードできることがあります。途中から文字が欠けた文字列は修復できません。デコードに失敗したら、元の場所から完全な文字列を新たにコピーしてください。"},{"question":"デコードした画像が予想より小さく見えるのはなぜですか？","answer":"デコードした画像は、元のファイルとまったく同じサイズです。想像していたより小さいだけかもしれません。文字列からデコードされた64×64のアイコンは小さな画像で、違う形式でダウンロードしてもピクセルは増えません。ダウンロードする前に、プレビューの横に表示されるサイズを確認しましょう。"},{"question":"複数のBase64文字列を一度にデコードできますか？","answer":"ツールは一度に1つの文字列をデコードします。文字列を貼り付けて画像をダウンロードし、入力をクリアして次の文字列を貼り付けます。クリアボタンを使えば長い文字列を素早く消せるため、数千文字を手で選択して削除する必要がありません。"},{"question":"知らない人から受け取ったBase64文字列をデコードするのは安全ですか？","answer":"デコード自体は安全です。ツールはブラウザ内でローカルにテキストを画像ファイルに変えるだけだからです。文字列と一緒に来たファイルを開いたり実行したりせず、画像の内容も盲目的に信じないでください。デコードされた画像はピクセルにすぎませんが、その周りのメッセージはフィッシングの試みかもしれません。"},{"question":"デコードした画像の背景が透明ではなく白いのはなぜですか？","answer":"まずチェック柄のプレビューを確認しましょう。プレビューで透明度が見える場合は、JPGではなく「元の形式」またはPNGでダウンロードしてください。JPGは透明な部分を塗りつぶすからです。プレビューでも白く見える場合は、元の画像に本当に白い背景があり、どのダウンロード形式でもなかった透明度を取り戻すことはできません。"},{"question":"Base64文字列をオフラインでデコードできますか？","answer":"はい。ページが読み込まれた後なら可能です。すべてのデコードはサーバーを使わずにブラウザで行われるため、初回のページ読み込みの後はインターネット接続は不要です。飛行機の中や安全なオフィス、接続が不安定な場所でも役立ちます。"}];
